const MESSAGE = "Hello from Crossmint";
const CHAIN = "base-sepolia";
const WALLET_TYPE = "evm-smart-wallet";

async function main() {
  const resultPayload = {
    chain: CHAIN,
    message: MESSAGE,
    signature: "mock-signature",
    wallet_type: WALLET_TYPE,
  };

  try {
    const { createCrossmint, CrossmintWallets } = require("@crossmint/wallets-sdk");
    const apiKey = process.env.CROSSMINT_API_KEY;

    if (!apiKey) {
      throw new Error("Missing CROSSMINT_API_KEY environment variable.");
    }

    const crossmint = createCrossmint({ apiKey });
    const walletsClient = new CrossmintWallets({ client: crossmint });

    const wallet = await walletsClient.getOrCreateWallet({
      chain: CHAIN,
      walletType: WALLET_TYPE,
      owner: {
        type: "user",
        userId: "demo-user-001",
      },
      serverSideRecovery: true,
    });

    if (!wallet?.signMessage) {
      throw new Error("Wallet signing capability not available.");
    }

    const signature = await wallet.signMessage({ message: MESSAGE });
    resultPayload.signature = signature;
  } catch (error) {
    resultPayload.error = error instanceof Error ? error.message : String(error);
  }

  await fs.promises.mkdir(path.dirname(OUTPUT_PATH), { recursive: true });
  await fs.promises.writeFile(
    OUTPUT_PATH,
    `${JSON.stringify(resultPayload, null, 2)}\n`,
    "utf8"
  );
}

